import Link from'next/link';import{getWorkspaceInvoices}from'@/lib/supabase/workspace';import{PageHead}from'@/components/shell';
export default async function Vendors(){const invoices=await getWorkspaceInvoices(),vendors=Array.from(new Set(invoices.map(i=>i.vendor))).map(name=>{const rows=invoices.filter(i=>i.vendor===name);const total=rows.reduce((s,i)=>s+i.total,0);return{name,rows,total,last:rows.map(i=>i.invoiceDate).sort().at(-1),reviews:rows.filter(i=>i.status==='review_required').length,duplicates:rows.filter(i=>i.reason.toLowerCase().includes('duplicate')).length}});return <><PageHead title="Vendors" subtitle="Supplier invoice volume and exception patterns."/><section className="panel" style={{padding:0,overflow:'hidden'}}>{vendors.length?<table><thead><tr><th>Vendor</th><th>Invoice count</th><th>Total value</th><th>Average invoice</th><th>Last invoice</th><th>Reviews</th><th>Duplicates</th></tr></thead><tbody>{vendors.map(v=><tr key={v.name}><td className="primarytext">{v.name}</td><td>{v.rows.length}</td><td className="primarytext">${v.total.toLocaleString()}</td><td>${(v.total/v.rows.length).toLocaleString(undefined,{maximumFractionDigits:2})}</td><td>{v.last}</td><td><Link href="/review">{v.reviews}</Link></td><td>{v.duplicates}</td></tr>)}</tbody></table>:<div className="secondary" style={{padding:20}}>No vendor data available.</div>}</section><div className="secondary" style={{marginTop:12}}>Vendor metrics are computed from invoices in the active workspace.</div></>}
